119	
120	    /** Derived duplicate-detection key: normalized telephone, email (or empty) and household id
121	     *  joined with {@code '|'}. Two owners are duplicates only when their whole key matches, so a
122	     *  shared telephone alone (with matching email) is a collision regardless of household. */
123	    @Transient
124	    public String getIdentityKey() {
125	        return (this.telephone == null ? "" : this.telephone) + "|"
126	            + (this.email == null ? "" : this.email) + "|";
