128	
129	    /** Membership number formatted {@code <customerCode>-M<YY>}, e.g. {@code SMI-0007-M26}. */
130	    @Transient
131	    public String getMembershipNumber() {
132	        return MembershipNumber.of(this.customerCode, this.registrationDate);
133	    }
134	
135	    /** Luhn check digit over the digits of the {@code customerCode}. */
136	    @Transient
137	    public Integer getCheckDigit() {
138	        return CheckDigit.of(this.customerCode);
139	    }
140	
