142	        return this.namesakeCount;
143	    }
144	
145	    public void setNamesakeCount(Integer namesakeCount) {
146	        this.namesakeCount = namesakeCount;
147	    }
148	
149	    /** Number of members in this owner's household (owners sharing {@link #getHouseholdId()})
150	     *  captured when the owner was created, including this owner. */
151	    public Integer getHouseholdMemberCount() {
152	        return this.householdMemberCount;
153	    }
154	
155	    public void setHouseholdMemberCount(Integer householdMemberCount) {
156	        this.householdMemberCount = householdMemberCount;
157	    }
158	
159	    /** True when this owner, at creation, shared an existing owner's last name and postcode
160	     *  but had a different telephone (a soft, non-hard duplicate). */
161	    public Boolean getPossibleDuplicate() {
162	        return this.possibleDuplicate;
163	    }
164	
165	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
