199	        this.postcode = postcode;
200	    }
201	
202	    public String getCity() {
203	        return this.city;
204	    }
205	
206	    public void setCity(String city) {
207	        this.city = city;
208	    }
209	
210	    public String getTelephone() {
211	        return this.telephone;
212	    }
213	
214	    public void setTelephone(String telephone) {
215	        this.telephone = telephone == null ? null : PhoneNumbers.toE164(telephone);
216	    }
217	
218	    protected Set<Pet> getPetsInternal() {
219	        if (this.pets == null) {
220	            this.pets = new HashSet<>();
221	        }
222	        return this.pets;
223	    }
224	
