226	        this.pets = pets;
227	    }
228	
229	    public List<Pet> getPets() {
230	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
231	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
232	        return Collections.unmodifiableList(sortedPets);
233	    }
234	
235	    public void setPets(List<Pet> pets) {
236	        this.pets = new HashSet<>(pets);
237	    }
238	
239	    public void addPet(Pet pet) {
240	        getPetsInternal().add(pet);
241	        pet.setOwner(this);
242	    }
243	
244	    /**
245	     * Return the Pet with the given name, or null if none found for this Owner.
246	     *
247	     * @param name to test
248	     * @return true if pet name is already in use
249	     */
250	    public Pet getPet(String name) {
251	        return getPet(name, false);
252	    }
253	
254	    /**
255	     * Return the Pet with the given name, or null if none found for this Owner.
256	     *
257	     * @param name to test
258	     * @return true if pet name is already in use
259	     */
260	    public Pet getPet(String name, boolean ignoreNew) {
261	        name = name.toLowerCase();
262	        for (Pet pet : getPetsInternal()) {
263	            if (!ignoreNew || !pet.isNew()) {
264	                String compName = pet.getName();
265	                compName = compName.toLowerCase();
266	                if (compName.equals(name)) {
